def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in component)
            r1 = max(y for y, x in component)
            c0 = min(x for y, x in component)
            c1 = max(x for y, x in component)

            depth = {}
            for y, x in component:
                color = grid[y][x]
                d = min(y-r0, r1-y, x-c0, c1-x)
                depth[color] = min(depth.get(color, d), d)

            layers = sorted(depth, key=lambda color: depth[color])
            reverse = {color: layers[-1-i] for i, color in enumerate(layers)}
            for y, x in component:
                out[y][x] = reverse[grid[y][x]]

    return out
